import type { BankQuestion } from "@/lib/bank";

/** Human Health and Disease, Microbes in Human Welfare (Biology (NEET)): 90 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-health-microbes-1","question":"The Widal test is used to confirm:","options":["Malaria","AIDS","Typhoid","Tuberculosis"],"answer":2,"explanation":"Typhoid fever, caused by Salmonella typhi, is confirmed by the Widal test.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-health-microbes-2","question":"Milk is converted into curd by:","options":["Propionibacterium sharmanii","Lactic acid bacteria such as Lactobacillus","Saccharomyces cerevisiae","Acetobacter aceti"],"answer":1,"explanation":"Lactobacillus and other lactic acid bacteria (LAB) produce acids that coagulate and partially digest milk proteins.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-health-microbes-3","question":"Malaria is transmitted to humans by the bite of:","options":["The female Anopheles mosquito","The male Culex mosquito","The female Aedes mosquito","The housefly"],"answer":0,"explanation":"The female Anopheles mosquito is the vector of Plasmodium. Aedes transmits dengue and chikungunya.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-health-microbes-4","question":"The chills and high fever recurring every three to four days in malaria are caused by the release of a toxic substance called:","options":["Haemozoin","Serotonin","Interferon","Histamine"],"answer":0,"explanation":"When Plasmodium ruptures the RBCs it releases the toxin haemozoin, which causes the chill and high fever recurring every three to four days.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-5","question":"An antibody molecule is represented as H₂L₂ because it has:","options":["Two hinges and two loops","Two hydrophobic and two lipophilic domains","Two heavy and two light peptide chains","Two haem groups and two lipid chains"],"answer":2,"explanation":"Each antibody has four peptide chains, two small light chains and two longer heavy chains.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-6","question":"Virus-infected cells secrete proteins that protect non-infected cells from further viral infection. These proteins are:","options":["Interferons","Histamines","Statins","Antibodies"],"answer":0,"explanation":"Interferons form the cytokine barrier of innate immunity. Antibodies are made by B-lymphocytes as part of acquired immunity.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-7","question":"Statins, used for lowering blood cholesterol, are produced by the yeast:","options":["Monascus purpureus","Trichoderma polysporum","Penicillium notatum","Saccharomyces cerevisiae"],"answer":0,"explanation":"Statins from Monascus purpureus competitively inhibit the enzyme responsible for cholesterol synthesis. Trichoderma polysporum produces cyclosporin A.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-8","question":"Besides making curd, lactic acid bacteria improve its nutritional quality by increasing its content of:","options":["Vitamin C","Vitamin D","Vitamin K","Vitamin B₁₂"],"answer":3,"explanation":"LAB increase vitamin B₁₂ in curd, and in our stomach they also check disease-causing microbes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-9","question":"Methanogens such as Methanobacterium, found in the rumen of cattle, produce large amounts of:","options":["Hydrogen sulphide only","Lactic acid","Ethanol","Methane"],"answer":3,"explanation":"Methanogens grow anaerobically on cellulosic material and produce methane along with CO₂ and H₂; cattle dung rich in them is used to make biogas (gobar gas).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-10","question":"In the life cycle of Plasmodium, fertilisation and development take place in:","options":["The human red blood cells","The salivary glands of the mosquito","The human liver cells","The stomach (gut) of the female Anopheles mosquito"],"answer":3,"explanation":"Gametocytes taken up with blood fuse in the mosquito's stomach; the sporozoites formed move to the salivary glands and enter humans at the next bite. RBCs are where gametocytes develop.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-11","question":"Ringworm is caused by fungi of all of the following genera EXCEPT:","options":["Microsporum","Trichophyton","Alternaria","Epidermophyton"],"answer":2,"explanation":"Microsporum, Trichophyton and Epidermophyton cause ringworm, which is favoured by heat and moisture in skin folds such as the groin. Alternaria is a deuteromycete not linked to ringworm.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-12","question":"The mucosa-associated lymphoid tissue (MALT) present in the linings of the respiratory, digestive and urinogenital tracts constitutes about what fraction of the lymphoid tissue in the human body?","options":["About 10%","About 90%","About 25%","About 50%"],"answer":3,"explanation":"MALT makes up about 50% of the lymphoid tissue in the human body.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-13","question":"After HIV enters the body, which cells continue to produce virus and are therefore called an 'HIV factory'?","options":["Red blood cells","Helper T-lymphocytes","B-lymphocytes","Macrophages"],"answer":3,"explanation":"HIV first enters macrophages, where its RNA is copied into DNA by reverse transcriptase; macrophages keep producing virus. It then enters helper T-lymphocytes, whose numbers fall steadily.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-14","question":"Biological response modifiers such as α-interferon are used in cancer treatment because they:","options":["Directly cut the DNA of cancer cells","Activate the immune system and help in destroying the tumour","Act as alkylating chemotherapeutic agents","Block blood supply to the tumour by clotting"],"answer":1,"explanation":"Tumour cells avoid detection by the immune system; α-interferon activates the immune system to help destroy the tumour.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-15","question":"Allergic reactions are due to the release of chemicals such as histamine and serotonin from:","options":["Red blood cells, after IgM antibodies are produced","Mast cells, after antibodies of the IgE type are produced","Platelets, after IgA antibodies are produced","Neutrophils, after IgG antibodies are produced"],"answer":1,"explanation":"Allergens trigger IgE antibodies, and mast cells release histamine and serotonin. Antihistamines, adrenalin and steroids quickly reduce the symptoms.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-16","question":"During secondary treatment of sewage, what happens to the activated sludge after it settles in the settling tank?","options":["It is burnt to release methane","All of it is pumped back into the aeration tank","All of it is discharged directly into rivers","A small part is pumped back into the aeration tank as inoculum and the major part goes to anaerobic sludge digesters"],"answer":3,"explanation":"A small part of the activated sludge serves as inoculum in the aeration tank; the rest goes to anaerobic sludge digesters, where bacteria digest it and produce methane, H₂S and CO₂ (biogas).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-17","question":"Baculoviruses used as biological control agents against insects and other arthropods mostly belong to the genus:","options":["Lentivirus","Nucleopolyhedrovirus","Rhinovirus","Retrovirus"],"answer":1,"explanation":"Most baculoviruses used as biocontrol agents are Nucleopolyhedroviruses. They are species-specific with narrow-spectrum effects and harm no non-target organisms.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-18","question":"Fungi of the genus Glomus, forming mycorrhiza with plant roots, mainly help the plant by:","options":["Fixing atmospheric nitrogen in root nodules","Absorbing phosphorus from the soil and passing it to the plant","Killing insect larvae","Producing methane"],"answer":1,"explanation":"Glomus mycorrhizae absorb phosphorus from the soil; such plants also show resistance to root-borne pathogens, tolerance to salinity and drought, and better growth.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-19","question":"Match the disease with its pathogen and a feature.\nList I: (A) Typhoid (B) Pneumonia (C) Common cold (D) Amoebiasis\nList II: (1) Rhinoviruses; infect the nose and respiratory passage but not the lungs (2) Entamoeba histolytica; stools with excess mucus and blood clots (3) Salmonella typhi; intestinal perforation in severe cases (4) Streptococcus pneumoniae; lips and finger nails may turn grey to bluish","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":1,"explanation":"Salmonella typhi causes typhoid (intestinal perforation in severe cases); Streptococcus pneumoniae causes pneumonia with bluish lips and nails; rhinoviruses cause the common cold; Entamoeba histolytica causes amoebic dysentery.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-20","question":"How many of the following statements about immunity are correct?\n(i) Colostrum, the yellowish fluid secreted in the initial days of lactation, has abundant IgA antibodies.\n(ii) Active immunity is slow and takes time to give its full effective response.\n(iii) The hepatitis B vaccine is produced from yeast by recombinant DNA technology.\n(iv) B-lymphocytes mediate the cell-mediated immunity responsible for graft rejection.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. Cell-mediated immunity, including graft rejection, is mediated by T-lymphocytes; B-lymphocytes produce antibodies (humoral immunity).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-21","question":"Match the drug with its effect.\nList I: (A) Heroin (B) Cocaine (C) Cannabinoids\nList II: (1) Interferes with the transport of the neurotransmitter dopamine (2) A depressant that slows down body functions (3) Known for their effects on the cardiovascular system","options":["A-3, B-1, C-2","A-1, B-2, C-3","A-2, B-3, C-1","A-2, B-1, C-3"],"answer":3,"explanation":"Heroin (diacetylmorphine, from morphine of the poppy) is a depressant; cocaine from Erythroxylum coca interferes with dopamine transport; cannabinoids from Cannabis sativa affect the cardiovascular system.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-22","question":"Assertion (A): AIDS patients become susceptible to infections by Mycobacterium, viruses, fungi and parasites like Toxoplasma.\nReason (R): The number of helper T-lymphocytes progressively decreases in a person infected with HIV.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: helper T-cells are central to the immune response, so their decline makes the person immunodeficient and unable to fight even ordinary infections.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-23","question":"How many of the following statements about cancer are correct?\n(i) Biopsy and histopathological studies of the tissue are used to detect cancer.\n(ii) MRI uses ionising X-rays to generate three-dimensional images.\n(iii) Antibodies against cancer-specific antigens are used for detection of certain cancers.\n(iv) Cancer cells show contact inhibition.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iii) are correct. MRI uses strong magnetic fields and non-ionising radiation, and cancer cells have lost contact inhibition, so they keep dividing to form tumours.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-24","question":"Which microbe–product pair is INCORRECTLY matched?","options":["Acetobacter aceti: acetic acid","Trichoderma polysporum: cyclosporin A","Streptococcus: streptokinase","Clostridium butylicum: citric acid"],"answer":3,"explanation":"Clostridium butylicum produces butyric acid; citric acid comes from the fungus Aspergillus niger. Streptokinase is a clot buster, and cyclosporin A is an immunosuppressant for transplant patients.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-25","question":"How many of the following statements are correct?\n(i) Saccharomyces cerevisiae is used for making bread and for commercial production of ethanol.\n(ii) The large holes in Swiss cheese are due to CO₂ produced by Propionibacterium sharmanii.\n(iii) Roquefort cheese is ripened by growing specific fungi on it.\n(iv) Lipases are used in detergent formulations to remove oily stains from laundry.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT statements about microbes in household and industrial products.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-26","question":"Match the biocontrol agent or biofertiliser with its use.\nList I: (A) Bacillus thuringiensis (B) Trichoderma (C) Baculoviruses (D) Glomus\nList II: (1) Free-living fungi of root ecosystems effective against several plant pathogens (2) Phosphorus absorption through mycorrhiza (3) Control of butterfly caterpillars (4) Species-specific, narrow-spectrum insecticidal applications","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"answer":0,"explanation":"Bt spores are sprayed to kill caterpillars; Trichoderma controls plant pathogens; baculoviruses are narrow-spectrum insect pathogens; Glomus forms phosphorus-absorbing mycorrhiza.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-27","question":"Assertion (A): Penicillin was discovered by Alexander Fleming while working on Staphylococci bacteria.\nReason (R): The full potential of penicillin as an effective antibiotic was established by Ernest Chain and Howard Florey.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but R describes later work and does not explain how Fleming discovered penicillin. Fleming, Chain and Florey shared the Nobel Prize in 1945.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-28","question":"How many of the following statements are correct?\n(i) Dengue and chikungunya are transmitted by Aedes mosquitoes.\n(ii) Gambusia, a fish introduced into ponds, feeds on mosquito larvae.\n(iii) Elephantiasis is caused by Wuchereria bancrofti and W. malayi.\n(iv) Ascaris infection is spread by the bite of infected mosquitoes.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. Ascaris eggs pass out with the faeces of infected persons, and a healthy person gets infected through contaminated water, vegetables and fruits.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-29","question":"All of the following are barriers of innate immunity EXCEPT:","options":["Neutrophils, monocytes and natural killer cells","Antibodies produced by plasma cells","Mucus coating the epithelium of the respiratory tract","Acid in the stomach and tears from the eyes"],"answer":1,"explanation":"Physical (skin, mucus), physiological (stomach acid, saliva, tears), cellular (PMNL-neutrophils, monocytes, NK cells, macrophages) and cytokine (interferon) barriers are innate. Antibodies from plasma cells belong to acquired immunity.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-30","question":"Arrange the events after HIV enters the human body in the correct order.\n(i) Viral DNA gets incorporated into the host cell's DNA\n(ii) The virus enters macrophages\n(iii) The RNA genome is copied into viral DNA by reverse transcriptase\n(iv) HIV enters helper T-lymphocytes, replicates and releases progeny viruses into blood\n(v) Infected cells produce virus particles","options":["(ii), (i), (iii), (v), (iv)","(iv), (iii), (i), (v), (ii)","(ii), (iii), (v), (i), (iv)","(ii), (iii), (i), (v), (iv)"],"answer":3,"explanation":"HIV enters macrophages, reverse transcriptase copies its RNA into DNA, the DNA integrates into the host genome and directs the cell to make virus; the virus then attacks helper T-lymphocytes.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-health-microbes-31", "question": "Which of the following is an autoimmune disease?", "options": ["Rheumatoid arthritis", "Typhoid", "Ascariasis", "Common cold"], "answer": 0, "explanation": "In rheumatoid arthritis the immune system attacks the body's own cells. Typhoid, ascariasis and common cold are infectious diseases.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-health-microbes-32", "question": "The primary lymphoid organs, where immature lymphocytes differentiate into antigen-sensitive lymphocytes, are:", "options": ["Spleen and lymph nodes", "Bone marrow and thymus", "Tonsils and appendix", "Peyer's patches and spleen"], "answer": 1, "explanation": "Bone marrow and thymus are primary lymphoid organs; spleen, lymph nodes, tonsils, Peyer's patches and appendix are secondary lymphoid organs.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-health-microbes-33", "question": "Ascariasis, in which a person suffers internal bleeding, muscular pain, fever, anaemia and blockage of the intestinal passage, is caused by:", "options": ["A virus", "A protozoan", "A helminth (roundworm)", "A fungus"], "answer": 2, "explanation": "Ascaris, the common roundworm, is an intestinal helminth; its eggs pass out with faeces and spread through contaminated water, vegetables and fruits.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-health-microbes-34", "question": "To save the country's major rivers from pollution, the Ministry of Environment and Forests initiated:", "options": ["Project Tiger", "Joint Forest Management", "The Green Revolution", "Ganga Action Plan and Yamuna Action Plan"], "answer": 3, "explanation": "Under the Ganga and Yamuna Action Plans, many new sewage treatment plants were to be built so that only treated sewage reaches the rivers.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-health-microbes-35", "question": "Opioids such as heroin act by binding to specific opioid receptors present in the:", "options": ["Central nervous system and gastrointestinal tract", "Kidneys and liver", "Lungs and heart", "Skin and skeletal muscles"], "answer": 0, "explanation": "Opioid receptors are located in the central nervous system and the gastrointestinal tract; heroin, acting through them, is a depressant that slows body functions.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-health-microbes-36", "question": "In biological pest control, ladybirds and dragonflies are useful for getting rid of, respectively:", "options": ["Mosquitoes and aphids", "Aphids and mosquitoes", "Butterfly caterpillars and aphids", "Termites and mosquitoes"], "answer": 1, "explanation": "Ladybirds feed on aphids and dragonflies prey on mosquitoes.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-health-microbes-37", "question": "Bottled fruit juices are clearer than home-made juices because they are clarified using:", "options": ["Lipases and amylases", "Streptokinase", "Pectinases and proteases", "Cellulases and lysozyme"], "answer": 2, "explanation": "Pectinases and proteases, enzymes from microbes, break down the pectin and proteins that make juice cloudy.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-health-microbes-38", "question": "Nicotine in tobacco raises blood pressure and heart rate because it:", "options": ["Destroys red blood cells", "Inhibits dopamine transport", "Blocks opioid receptors", "Stimulates the adrenal gland to release adrenaline and noradrenaline into the blood"], "answer": 3, "explanation": "Nicotine stimulates the adrenal medulla to release adrenaline and noradrenaline, both of which raise blood pressure and heart rate.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-health-microbes-39", "question": "The antibody-mediated immune response produced by B-lymphocytes is called the humoral immune response because:", "options": ["The antibodies are found in the blood", "It is carried out by T-lymphocytes", "It occurs only in the lymph nodes", "It involves only physical barriers"], "answer": 0, "explanation": "B-lymphocytes produce antibodies that circulate in the blood (a body 'humour'), hence humoral immunity; T-lymphocytes mediate cell-mediated immunity.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-health-microbes-40", "question": "In malaria, the sporozoites injected by the bite of an infected female Anopheles mosquito first:", "options": ["Multiply in the red blood cells", "Multiply in the liver cells", "Undergo sexual reproduction in human blood", "Enter the salivary glands of the human"], "answer": 1, "explanation": "Sporozoites, the infectious form, first multiply in liver cells and then attack red blood cells, which rupture and release haemozoin.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-41", "question": "Which insects act as mechanical carriers that transmit the parasite of amoebic dysentery from faeces of infected persons to food and food products?", "options": ["Female Anopheles mosquitoes", "Aedes mosquitoes", "Houseflies", "Sandflies"], "answer": 2, "explanation": "Houseflies carry Entamoeba histolytica cysts mechanically and contaminate food and water; amoebiasis is a disease of the large intestine.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-42", "question": "In filariasis, the filarial worms live for many years and cause chronic inflammation, normally in the:", "options": ["Small intestine", "Liver cells", "Lungs", "Lymphatic vessels of the lower limbs"], "answer": 3, "explanation": "Wuchereria lives in the lymphatic vessels, mostly of the lower limbs, causing elephantiasis; genital organs may also be deformed. It spreads by the bite of female mosquito vectors.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-43", "question": "In the case of leukaemia, cancer is detected by:", "options": ["Blood and bone marrow tests for increased cell counts", "MRI of the brain", "Biopsy of the skin", "Widal test"], "answer": 0, "explanation": "Leukaemias are blood cancers, so blood and bone marrow tests showing increased cell counts are used for detection.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-44", "question": "Which statement about the thymus is correct?", "options": ["It is a secondary lymphoid organ", "It is quite large at birth but keeps reducing in size with age, becoming very small by puberty", "It is small at birth and grows larger until old age", "It is the site where all blood cells are produced"], "answer": 1, "explanation": "The thymus, a primary lymphoid organ where T-lymphocytes mature, is large at birth and shrinks with age. Bone marrow is where all blood cells, including lymphocytes, are produced.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-45", "question": "The spleen, a large bean-shaped secondary lymphoid organ, mainly:", "options": ["Produces all blood cells in adults", "Is the site of T-lymphocyte maturation", "Contains lymphocytes and phagocytes, filters the blood by trapping blood-borne microorganisms, and is a large reservoir of erythrocytes", "Traps microorganisms present in lymph and tissue fluid only"], "answer": 2, "explanation": "The spleen filters blood and stores erythrocytes. Lymph nodes trap microorganisms in lymph and tissue fluid, and the thymus is where T cells mature.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-46", "question": "During primary treatment of sewage, the settled solids and the liquid above them are called, respectively:", "options": ["Effluent and primary sludge", "Biogas and supernatant", "Activated sludge and flocs", "Primary sludge and effluent"], "answer": 3, "explanation": "All solids that settle form the primary sludge; the supernatant forms the effluent, which is taken for secondary (biological) treatment.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-47", "question": "In anaerobic sludge digesters, other bacteria digest the bacteria and fungi present in the sludge. The gases produced are:", "options": ["Methane, hydrogen sulphide and carbon dioxide", "Oxygen and nitrogen", "Ammonia and chlorine", "Carbon monoxide and hydrogen only"], "answer": 0, "explanation": "Anaerobic digestion of the sludge yields a mixture of methane, H₂S and CO₂ that forms biogas, a usable fuel.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-48", "question": "The time lag between HIV infection and the appearance of AIDS symptoms is usually:", "options": ["A few hours", "5 to 10 years", "Two to three weeks", "A few days"], "answer": 1, "explanation": "The lag may range from a few months to many years, usually 5–10 years, during which the person can still transmit the virus.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-49", "question": "How many of the following statements about vaccination and immunity are correct?\n(i) A vaccine introduces a preparation of antigenic proteins of a pathogen or inactivated/weakened pathogens into the body.\n(ii) The antibodies produced in the body neutralise the pathogenic agents during actual infection, and memory B and T cells are generated.\n(iii) An injection of preformed antitoxin against tetanus confers active immunity.\n(iv) The injection given after a snakebite contains preformed antibodies against the snake venom.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are correct. Injecting preformed antibodies or antitoxin, as for tetanus or snakebite, gives passive immunity, which is quick but short-lived.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-50", "question": "Match the drug or plant with its description.\nList I: (A) Cannabinoids (B) Barbiturates (C) Morphine (D) Datura\nList II: (1) Extracted from the latex of the poppy Papaver somniferum (2) Normally prescribed to help patients cope with depression and insomnia, but often abused (3) Plant with hallucinogenic properties (4) Obtained from the inflorescence of Cannabis sativa", "options": ["A-4, B-1, C-2, D-3", "A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3", "A-4, B-2, C-3, D-1"], "answer": 2, "explanation": "Cannabinoids come from the inflorescence of Cannabis sativa and morphine from poppy latex. Barbiturates, like amphetamines and benzodiazepines, are medicines for mental illness that are often abused, and Datura and Atropa belladonna are hallucinogenic plants.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-51", "question": "Assertion (A): Biogas plants are more often built in rural areas.\nReason (R): Cattle dung, which is rich in methanogenic bacteria and is the raw material for biogas, is available in large quantities in rural areas.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Biogas production depends on cattle dung (gobar), which is plentiful in villages; that availability is why the plants are mostly built in rural areas.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-52", "question": "How many of the following statements about the causes of cancer are correct?\n(i) Ionising radiations such as X-rays and gamma rays and non-ionising radiations such as UV cause DNA damage leading to neoplastic transformation.\n(ii) Cancer-causing viruses, called oncogenic viruses, have genes called viral oncogenes.\n(iii) Proto-oncogenes present in normal cells can, when activated under certain conditions, lead to oncogenic transformation.\n(iv) Benign tumours spread to distant sites through the blood.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iii) are correct. Benign tumours stay confined to their original location; it is malignant tumours that spread by metastasis.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-53", "question": "All of the following are side effects of anabolic steroid abuse in FEMALES EXCEPT:", "options": ["Deepening of the voice", "Abnormal menstrual cycles", "Enlargement of the clitoris", "Enlargement of the prostate gland"], "answer": 3, "explanation": "Enlargement of the prostate gland is a side effect seen in males, along with reduced testis size, decreased sperm production and breast enlargement. In females, steroids cause masculinisation, a deeper voice, abnormal cycles, clitoris enlargement and excess facial hair.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-54", "question": "Match the term related to sewage treatment with its description.\nList I: (A) Primary treatment (B) Secondary treatment (C) Flocs (D) Anaerobic sludge digester\nList II: (1) Masses of bacteria associated with fungal filaments forming mesh-like structures (2) Physical removal of particles by filtration and sedimentation (3) Tank in which biogas is produced from sludge (4) Biological treatment in which aerobic microbes consume organic matter", "options": ["A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3", "A-2, B-1, C-4, D-3", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "Primary treatment is physical; secondary treatment is biological, with flocs of bacteria and fungal filaments consuming organic matter in aeration tanks; the sludge is then digested anaerobically to produce biogas.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-55", "question": "Assertion (A): A second exposure to the same pathogen produces a highly intensified and faster immune response.\nReason (R): The first encounter with the pathogen generates memory B and T cells.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The primary response leaves memory cells; on a later encounter they mount the secondary (anamnestic) response, which is quicker and stronger.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-56", "question": "How many of the following statements about drug and alcohol abuse are correct?\n(i) Chronic use of drugs and alcohol damages the nervous system and the liver (cirrhosis).\n(ii) Use of drugs and alcohol during pregnancy adversely affects the foetus.\n(iii) Those who take drugs intravenously are more likely to get serious infections like AIDS and hepatitis B.\n(iv) Adolescence is the period roughly between 12 and 18 years of age.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Sharing needles spreads HIV and hepatitis B, alcohol causes liver cirrhosis, and adolescence (12–18 years) is a vulnerable phase for starting drug use.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-57", "question": "Match the microbe with its role.\nList I: (A) Anabaena (B) Rhizobium (C) Azotobacter (D) Methanobacterium\nList II: (1) Free-living nitrogen fixer in the soil (2) Biogas production (3) Cyanobacterium fixing nitrogen in paddy fields (4) Symbiotic nitrogen fixer in legume root nodules", "options": ["A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "Anabaena (with Nostoc and Oscillatoria) fixes nitrogen in paddy fields, Rhizobium in legume nodules, Azotobacter and Azospirillum are free-living soil fixers, and Methanobacterium produces methane in biogas plants.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-58", "question": "How many of the following statements about HIV and AIDS are correct?\n(i) HIV is a retrovirus with an RNA genome.\n(ii) AIDS is transmitted by touch or physical contact with an infected person.\n(iii) ELISA is a widely used diagnostic test for AIDS.\n(iv) Antiretroviral drugs completely cure AIDS.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (iii) are correct. AIDS spreads through body fluids (sexual contact, infected blood, needles, mother to foetus), not touch, and antiretroviral drugs only prolong life; they do not cure it.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-59", "question": "Match the barrier of innate immunity with its example.\nList I: (A) Physical barrier (B) Physiological barrier (C) Cellular barrier (D) Cytokine barrier\nList II: (1) Interferons secreted by virus-infected cells (2) Mucus coating the epithelium of the respiratory tract (3) Acid in the stomach and tears from the eyes (4) Natural killer lymphocytes and neutrophils", "options": ["A-3, B-2, C-4, D-1", "A-2, B-3, C-1, D-4", "A-2, B-3, C-4, D-1", "A-2, B-4, C-3, D-1"], "answer": 2, "explanation": "Skin and mucus are physical barriers, stomach acid, saliva and tears physiological, PMNL-neutrophils, monocytes, NK cells and macrophages cellular, and interferons the cytokine barrier.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-health-microbes-60", "question": "How many of the following statements about microbes in household and industrial products are correct?\n(i) Toddy, a traditional drink of southern India, is made by fermenting sap from palms.\n(ii) The puffed-up appearance of dough for dosa and idli is due to CO₂ produced by bacteria.\n(iii) Wine and beer are produced without distillation, whereas whisky, brandy and rum are produced by distillation of the fermented broth.\n(iv) Penicillin was the first antibiotic to be discovered.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Microbes ferment palm sap for toddy and dough for idli and dosa, distillation separates spirits from wine and beer, and penicillin was the first antibiotic discovered.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-health-microbes-61","question":"Malignant malaria, the most serious form of malaria that can even be fatal, is caused by:","options":["Plasmodium vivax","Plasmodium malariae","Plasmodium falciparum","Entamoeba histolytica"],"answer":2,"explanation":"Plasmodium falciparum causes malignant malaria. P. vivax and P. malariae cause milder malaria, and Entamoeba histolytica causes amoebiasis.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-health-microbes-62","question":"Streptokinase, used as a 'clot buster' to remove clots from the blood vessels of patients who have had a myocardial infarction, is obtained from the bacterium:","options":["Streptococcus","Staphylococcus","Monascus","Clostridium"],"answer":0,"explanation":"Streptokinase is produced by Streptococcus and modified by genetic engineering. Monascus purpureus, a yeast, gives statins.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-health-microbes-63","question":"Lipases are added to detergent formulations to:","options":["Make the detergent foam more","Remove oily stains from laundry","Bleach coloured fabrics","Kill bacteria on clothes"],"answer":1,"explanation":"Lipases break down fats, which helps to remove oily stains from laundry. Pectinases and proteases are used to clarify bottled juices.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-health-microbes-64","question":"The old 'good humour' hypothesis of health was disproved by:","options":["Louis Pasteur's work on fermentation","Edward Jenner's vaccination against smallpox","Alexander Fleming's discovery of penicillin","William Harvey's discovery of blood circulation using the experimental method, and the use of a thermometer to show normal body temperature in persons with 'black bile'"],"answer":3,"explanation":"Harvey's experimental discovery of blood circulation, together with thermometer readings showing normal body temperature in persons said to have black bile, disproved the 'good humour' hypothesis.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-65","question":"Mary Mallon, nicknamed 'Typhoid Mary', is a classic example of:","options":["A cook who was a typhoid carrier and spread the disease for several years through the food she prepared","The scientist who first isolated Salmonella typhi","The first patient cured of typhoid by penicillin","A nurse who developed the Widal test"],"answer":0,"explanation":"Mary Mallon was a cook and a typhoid carrier who kept spreading typhoid through the food she prepared. This shows how a carrier can spread a disease without being ill.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-66","question":"The large holes in Swiss cheese are produced by the carbon dioxide released by:","options":["Lactobacillus","Saccharomyces cerevisiae","Propionibacterium sharmanii","Penicillium notatum"],"answer":2,"explanation":"Propionibacterium sharmanii releases a large amount of CO2, which forms the holes in Swiss cheese. Roquefort cheese, by contrast, is ripened by growing specific fungi on it.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-67","question":"Allergic responses such as sneezing, watery eyes and difficulty in breathing involve antibodies of the type:","options":["IgA","IgE","IgG","IgM"],"answer":1,"explanation":"Allergy is an exaggerated response to allergens such as dust mites, pollen and animal dander, and it involves IgE antibodies. IgA is the main antibody in colostrum.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-68","question":"The period of adolescence, a bridge between childhood and adulthood, is taken to be:","options":["8 to 12 years","12 to 18 years","18 to 25 years","5 to 10 years"],"answer":1,"explanation":"Adolescence spans the period from 12 to 18 years of age. It brings many biological and behavioural changes, and is a vulnerable phase for starting drug or alcohol use.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-69","question":"Smoking reduces the concentration of haem-bound oxygen in the blood because it raises the blood content of:","options":["Nicotine","Carbon dioxide","Adrenaline","Carbon monoxide"],"answer":3,"explanation":"Smoking raises the carbon monoxide content of blood, which lowers the amount of oxygen bound to haem. Nicotine separately stimulates the adrenal gland to release adrenaline and noradrenaline.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-health-microbes-70","question":"A sustained high fever of 39 to 40 degrees C, with weakness, stomach pain, constipation, headache and loss of appetite, is typical of:","options":["Malaria","Typhoid","Common cold","Amoebiasis"],"answer":1,"explanation":"These are symptoms of typhoid, caused by Salmonella typhi. In malaria the high fever recurs every three to four days instead of being sustained.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-71","question":"Which statement about ringworm is correct?","options":["It is caused by Trichophyton, a bacterium","It spreads only through the bite of mosquitoes","It causes dry, scaly lesions with intense itching, and heat and moisture help the fungi grow in the groin or between the toes","It affects only the scalp and never the nails"],"answer":2,"explanation":"Ringworm is a fungal disease (Microsporum, Trichophyton, Epidermophyton) of the skin, nails and scalp. It is usually acquired from soil or by using an infected person's towels, clothes or comb.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-72","question":"The hepatitis B vaccine produced by recombinant DNA technology is made using:","options":["Escherichia coli","Agrobacterium tumefaciens","Yeast","Penicillium notatum"],"answer":2,"explanation":"Recombinant DNA technology allows large-scale production of antigenic polypeptides; the hepatitis B vaccine is produced from yeast.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-73","question":"The rejection of a transplanted organ by the body is due to:","options":["Antibodies of the IgE type","Innate immunity given by neutrophils only","Physiological barriers such as stomach acid","The cell-mediated immune response by T-lymphocytes"],"answer":3,"explanation":"The body can tell 'self' from 'non-self', and graft rejection is caused by the cell-mediated immune response. This is why tissue and blood group matching are needed and immunosuppressants are taken for life.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-74","question":"Heroin, commonly called smack, is chemically:","options":["Benzoylmethylecgonine obtained from coca leaves","Tetrahydrocannabinol obtained from hemp","Diacetylmorphine, a white, odourless, bitter crystalline compound obtained by acetylation of morphine","An alkaloid obtained from Datura seeds"],"answer":2,"explanation":"Heroin is diacetylmorphine, made by acetylating morphine extracted from the latex of the poppy Papaver somniferum. It is a depressant that slows down body functions.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-75","question":"Cocaine (coca alkaloid) is obtained from a plant native to South America. The plant is:","options":["Papaver somniferum","Cannabis sativa","Atropa belladonna","Erythroxylum coca"],"answer":3,"explanation":"Cocaine comes from Erythroxylum coca. Papaver gives opioids, Cannabis gives cannabinoids, and Atropa belladonna is a plant with hallucinogenic properties.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-76","question":"Cyclosporin A, used as an immunosuppressive agent in organ-transplant patients, is produced by:","options":["Trichoderma polysporum","Monascus purpureus","Aspergillus niger","Streptococcus"],"answer":0,"explanation":"The fungus Trichoderma polysporum produces cyclosporin A. Monascus purpureus gives statins, Aspergillus niger gives citric acid, and Streptococcus gives streptokinase.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-77","question":"All of the following are cyanobacteria that serve as important biofertilisers in paddy fields EXCEPT:","options":["Anabaena","Nostoc","Oscillatoria","Azospirillum"],"answer":3,"explanation":"Anabaena, Nostoc and Oscillatoria are autotrophic cyanobacteria that fix nitrogen and add organic matter to the soil. Azospirillum is a free-living nitrogen-fixing bacterium, not a cyanobacterium.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-78","question":"Which of the following is NOT obtained from Cannabis sativa?","options":["Marijuana","Hashish","Smack","Charas"],"answer":2,"explanation":"Marijuana, hashish, charas and ganja come from the inflorescences of Cannabis sativa. Smack is heroin, which comes from the opium poppy.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-79","question":"Match the microbe with the organic acid it produces.\nList I: (A) Aspergillus niger (B) Acetobacter aceti (C) Clostridium butylicum (D) Lactobacillus\nList II: (1) Lactic acid (2) Butyric acid (3) Acetic acid (4) Citric acid","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-1, B-3, C-2, D-4"],"answer":0,"explanation":"Aspergillus niger (a fungus) produces citric acid, Acetobacter aceti acetic acid, Clostridium butylicum butyric acid, and Lactobacillus lactic acid.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-80","question":"How many of the following statements about the common cold are correct?\n(i) It is caused by rhinoviruses.\n(ii) It infects the nose and respiratory passage but not the lungs.\n(iii) The symptoms usually last 3 to 7 days.\n(iv) It spreads by inhaling droplets from an infected person's cough or sneeze, or through contaminated objects such as pens, books, cups and door knobs.\n(v) The infection fills the alveoli with fluid, so the lips and finger nails turn bluish.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. Alveoli filling with fluid and bluish lips and nails are features of pneumonia, which infects the lungs.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-81","question":"From the following list, how many are secondary lymphoid organs?\nSpleen, lymph nodes, tonsils, Peyer's patches of the small intestine, appendix, bone marrow, thymus","options":["Three","Four","Six","Five"],"answer":3,"explanation":"Spleen, lymph nodes, tonsils, Peyer's patches and appendix are secondary lymphoid organs, where lymphocytes interact with antigens. Bone marrow and thymus are the primary lymphoid organs.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-82","question":"Match the cancer detection technique with its basis.\nList I: (A) Computed tomography (B) Magnetic resonance imaging (C) Biopsy and histopathology (D) Monoclonal antibodies\nList II: (1) Thin stained sections of a piece of the suspected tissue are examined (2) X-rays generate a three-dimensional image of the internal organs (3) Strong magnetic fields and non-ionising radiations detect changes in living tissue (4) Antibodies against cancer-specific antigens","options":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1","A-1, B-3, C-2, D-4"],"answer":1,"explanation":"CT uses X-rays to build a 3-D image, MRI uses strong magnetic fields and non-ionising radiation, biopsy examines stained tissue sections, and monoclonal antibodies target cancer-specific antigens.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-83","question":"From the following list, how many are side effects of anabolic steroid use in MALES?\nAcne, increased aggressiveness, reduction in size of the testicles, decreased sperm production, kidney and liver dysfunction, breast enlargement, premature baldness, enlargement of the prostate gland","options":["Five","Six","Seven","All eight"],"answer":3,"explanation":"All eight are side effects of anabolic steroids in males. Breast enlargement and premature baldness are easy to miss, but both are on the list.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-84","question":"From the following, how many alcoholic drinks are produced by distilling the fermented broth?\nWhisky, brandy, rum, wine, beer","options":["Two","Three","Four","Five"],"answer":1,"explanation":"Whisky, brandy and rum are produced by distilling the fermented broth. Wine and beer are produced without distillation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-85","question":"Assertion (A): The greater the BOD of waste water, the greater is its polluting potential.\nReason (R): BOD is the amount of oxygen that would be consumed if all the organic matter in one litre of water were oxidised by bacteria.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. BOD measures the organic matter present, so a higher BOD means more organic pollution; R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-86","question":"Assertion (A): Baculoviruses are desirable biocontrol agents in integrated pest management programmes in ecologically sensitive areas.\nReason (R): Baculoviruses are broad-spectrum insecticides that kill most insect species they contact.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true, but R is false. Baculoviruses (mostly Nucleopolyhedrovirus) are species-specific, narrow-spectrum insecticides that do not harm plants, mammals, birds, fish or non-target insects, which is why they suit sensitive areas.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-87","question":"Assertion (A): An organic farmer does not aim to eradicate the pests completely.\nReason (R): Beneficial predatory and parasitic insects that depend on the pests as food or hosts would not survive without them.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. The organic farmer keeps pests at manageable levels so that the natural enemies that depend on them also survive, so R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-88","question":"How many of the following statements about a biogas plant are correct?\n(i) It has a concrete tank, 10 to 15 feet deep, into which bio-wastes and a slurry of dung are fed.\n(ii) A floating cover over the slurry keeps rising as gas is produced.\n(iii) The spent slurry is removed through another outlet and may be used as fertiliser.\n(iv) The methanogens that produce the gas are aerobic bacteria.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. Methanogens such as Methanobacterium are anaerobic; they produce methane while growing on cellulosic material.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-89","question":"How many of the following statements about mycorrhiza formed by Glomus are correct?\n(i) The fungal partner absorbs phosphorus from the soil and passes it to the plant.\n(ii) The plant shows resistance to root-borne pathogens.\n(iii) The plant shows tolerance to salinity and drought.\n(iv) The fungus fixes atmospheric nitrogen in root nodules.","options":["Only three","Only one","Only two","All four"],"answer":0,"explanation":"Statements (i), (ii) and (iii) are correct; overall plant growth also increases. Nitrogen fixation in root nodules is done by Rhizobium, not by mycorrhizal fungi.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-health-microbes-90","question":"From the following, how many give PASSIVE immunity?\nAntibodies in colostrum received by an infant; antibodies passed from mother to foetus through the placenta; anti-tetanus antitoxin; antivenom injected after a snake bite; hepatitis B vaccine; recovery from chickenpox","options":["Two","Three","Four","Five"],"answer":2,"explanation":"The first four supply ready-made antibodies, so the immunity is passive. A vaccine and a natural infection make the body produce its own antibodies, which is active immunity.","difficulty":"very-hard","source":"NEET pattern"},
];

export default questions;
